package option

import (
	"fmt"
	"os"
)

type FileInfo struct {
	Path     string
	FileInfo os.FileInfo
}

func (e *FileInfo) String() string {
	return fmt.Sprintf(
		"{path: [%v], size: [%v], modeTime: [%v]}",
		e.Path,
		e.FileInfo.Size(),
		e.FileInfo.ModTime(),
	)
}

type ExtractMsg struct {
	FileInfo *FileInfo
	Error    error
}

func (e *ExtractMsg) String() string {
	if e.Error != nil {
		return fmt.Sprintf("{error: %v}", e.Error)
	}
	if e.FileInfo == nil {
		return "{fileInfo: nil}"
	}
	return fmt.Sprintf(
		"{path: [%v], size: [%v], modeTime: [%v]}",
		e.FileInfo.Path,
		e.FileInfo.FileInfo.Size(),
		e.FileInfo.FileInfo.ModTime(),
	)
}

package zip

import (
	"archive/zip"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path"
	"strings"
)

// ReadEntries sentinel errors.
var (
	ErrInvalidArchive = errors.New("zip: invalid archive")
	ErrUnsafePath     = errors.New("zip: unsafe entry path")
	ErrSymlink        = errors.New("zip: symbolic links are not allowed")
	ErrTooManyFiles   = errors.New("zip: too many files")
	ErrFileTooLarge   = errors.New("zip: file too large")
	ErrTotalTooLarge  = errors.New("zip: uncompressed content too large")
)

// ReadLimits bound in-memory ZIP processing.
type ReadLimits struct {
	MaxFiles      int
	MaxFileBytes  int64
	MaxTotalBytes int64
	RejectSymlink bool
}

// Entry is one regular file read from a ZIP archive.
type Entry struct {
	Name string
	Data []byte
	Mode os.FileMode
}

// ReadEntries reads regular files from a ZIP archive without extracting them.
// Names are normalized to slash-separated relative paths and traversal paths
// are rejected.
func ReadEntries(raw []byte, limits ReadLimits) ([]Entry, error) {
	reader, err := zip.NewReader(bytes.NewReader(raw), int64(len(raw)))
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrInvalidArchive, err)
	}
	entries := make([]Entry, 0, len(reader.File))
	var total int64
	for _, file := range reader.File {
		name, err := cleanRelativeName(file.Name)
		if err != nil {
			return nil, err
		}
		if name == "" || file.FileInfo().IsDir() {
			continue
		}
		mode := file.Mode()
		if limits.RejectSymlink && mode&os.ModeSymlink != 0 {
			return nil, fmt.Errorf("%w: %q", ErrSymlink, file.Name)
		}
		if !mode.IsRegular() {
			return nil, fmt.Errorf("%w: entry %q is not a regular file", ErrInvalidArchive, file.Name)
		}
		if limits.MaxFiles > 0 && len(entries) >= limits.MaxFiles {
			return nil, fmt.Errorf("%w: maximum is %d", ErrTooManyFiles, limits.MaxFiles)
		}
		content, err := readEntry(file, limits.MaxFileBytes)
		if err != nil {
			return nil, err
		}
		total += int64(len(content))
		if limits.MaxTotalBytes > 0 && total > limits.MaxTotalBytes {
			return nil, fmt.Errorf("%w: maximum is %d bytes", ErrTotalTooLarge, limits.MaxTotalBytes)
		}
		entries = append(entries, Entry{Name: name, Data: content, Mode: mode})
	}
	return entries, nil
}

func cleanRelativeName(name string) (string, error) {
	name = strings.ReplaceAll(name, "\\", "/")
	name = strings.TrimPrefix(name, "./")
	for _, part := range strings.Split(name, "/") {
		if part == ".." {
			return "", fmt.Errorf("%w: %q", ErrUnsafePath, name)
		}
	}
	cleaned := path.Clean(name)
	if cleaned == "." || cleaned == "" {
		return "", nil
	}
	if path.IsAbs(cleaned) || cleaned == ".." || strings.HasPrefix(cleaned, "../") ||
		(len(cleaned) >= 2 && cleaned[1] == ':') {
		return "", fmt.Errorf("%w: %q", ErrUnsafePath, name)
	}
	return cleaned, nil
}

func readEntry(file *zip.File, maxBytes int64) ([]byte, error) {
	reader, err := file.Open()
	if err != nil {
		return nil, fmt.Errorf("%w: open entry %q: %v", ErrInvalidArchive, file.Name, err)
	}
	defer reader.Close()
	source := io.Reader(reader)
	if maxBytes > 0 {
		source = io.LimitReader(reader, maxBytes+1)
	}
	content, err := io.ReadAll(source)
	if err != nil {
		return nil, fmt.Errorf("%w: read entry %q: %v", ErrInvalidArchive, file.Name, err)
	}
	if maxBytes > 0 && int64(len(content)) > maxBytes {
		return nil, fmt.Errorf("%w: entry %q exceeds %d bytes", ErrFileTooLarge, file.Name, maxBytes)
	}
	return content, nil
}

package zip

import (
	"archive/zip"
	"bytes"
	"errors"
	"os"
	"testing"
)

func TestReadEntries(t *testing.T) {
	t.Parallel()
	var raw bytes.Buffer
	writer := zip.NewWriter(&raw)
	header := &zip.FileHeader{Name: "skill/scripts/run.sh", Method: zip.Deflate}
	header.SetMode(0o755)
	entry, err := writer.CreateHeader(header)
	if err != nil {
		t.Fatal(err)
	}
	_, _ = entry.Write([]byte("#!/bin/sh\n"))
	if err := writer.Close(); err != nil {
		t.Fatal(err)
	}
	entries, err := ReadEntries(raw.Bytes(), ReadLimits{
		MaxFiles: 2, MaxFileBytes: 1024, MaxTotalBytes: 2048, RejectSymlink: true,
	})
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 1 || entries[0].Name != "skill/scripts/run.sh" ||
		entries[0].Mode&0o111 == 0 {
		t.Fatalf("entries = %+v", entries)
	}
}

func TestReadEntriesRejectsTraversalAndSymlink(t *testing.T) {
	t.Parallel()
	for _, test := range []struct {
		name string
		path string
		mode os.FileMode
		want error
	}{
		{name: "traversal", path: "../secret", mode: 0o644, want: ErrUnsafePath},
		{name: "nested traversal", path: "skill/../secret", mode: 0o644, want: ErrUnsafePath},
		{name: "windows absolute", path: `C:\secret`, mode: 0o644, want: ErrUnsafePath},
		{name: "symlink", path: "secret", mode: os.ModeSymlink | 0o777, want: ErrSymlink},
	} {
		test := test
		t.Run(test.name, func(t *testing.T) {
			var raw bytes.Buffer
			writer := zip.NewWriter(&raw)
			header := &zip.FileHeader{Name: test.path, Method: zip.Deflate}
			header.SetMode(test.mode)
			entry, err := writer.CreateHeader(header)
			if err != nil {
				t.Fatal(err)
			}
			_, _ = entry.Write([]byte("content"))
			if err := writer.Close(); err != nil {
				t.Fatal(err)
			}
			if _, err := ReadEntries(raw.Bytes(), ReadLimits{RejectSymlink: true}); !errors.Is(err, test.want) {
				t.Fatalf("error = %v, want %v", err, test.want)
			}
		})
	}
}

