            gfloat **fdata = (gfloat **)iter->data;

            fdata[0][pos] = fdata[1][pos] + fdata[2][pos] + fdata[3][pos] + fdata[4][pos];
            if (fdata[0][pos] > 1.0f)
              fdata[0][pos] = 1.0f;

            ++pos;
